-- Monetary wallets are independent of legacy token-credit wallets.
CREATE TABLE billing_catalogs (version CHAR(64) PRIMARY KEY,catalog JSON NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE billing_wallets (tenant_id VARCHAR(64) NOT NULL,currency CHAR(3) NOT NULL,balance_nano BIGINT UNSIGNED NOT NULL DEFAULT 0,held_nano BIGINT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,currency),CHECK(held_nano<=balance_nano),CHECK(balance_nano<=4503599627370496));
CREATE TABLE billing_credits (credit_id VARCHAR(128) PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,currency CHAR(3) NOT NULL,amount_nano BIGINT UNSIGNED NOT NULL,proof VARCHAR(256) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE billing_requests (request_id CHAR(32) PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,currency CHAR(3) NOT NULL,model VARCHAR(128) NOT NULL,price_version CHAR(64) NOT NULL,state VARCHAR(32) NOT NULL,reserved_nano BIGINT UNSIGNED NOT NULL,charged_nano BIGINT UNSIGNED NOT NULL DEFAULT 0,input_tokens BIGINT UNSIGNED NOT NULL DEFAULT 0,output_tokens BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),KEY ix_billing_scope(tenant_id,currency,created_at),KEY ix_billing_recovery(state,updated_at));
CREATE TABLE billing_attempts (request_id CHAR(32) NOT NULL,ordinal INT NOT NULL,provider VARCHAR(64) NOT NULL,usage_json JSON NULL,outcome VARCHAR(64) NULL,PRIMARY KEY(request_id,ordinal));
CREATE TABLE billing_audit (audit_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_id VARCHAR(128) NOT NULL,action VARCHAR(64) NOT NULL,proof VARCHAR(256) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
